/**
 * Percent-encoding primitives that mirror CPython's `urllib.parse`.
 *
 * Everything works on UTF-8 bytes so that `quote`/`unquote` round-trip
 * exactly the way Python's do, including the `errors='replace'` behaviour
 * of `unquote()` on malformed byte sequences.
 */

const HEX = '0123456789ABCDEF';

// Bytes Python never escapes, regardless of the `safe` argument.
const ALWAYS_SAFE =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZ' + 'abcdefghijklmnopqrstuvwxyz' + '0123456789' + '_.-~';

const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8'); // lenient: emits U+FFFD like errors='replace'

function safeTable(safe) {
  const table = new Uint8Array(256);
  for (const ch of ALWAYS_SAFE) table[ch.charCodeAt(0)] = 1;
  for (const ch of safe) {
    const code = ch.charCodeAt(0);
    if (code < 128) table[code] = 1;
  }
  return table;
}

const tableCache = new Map();

function tableFor(safe) {
  let table = tableCache.get(safe);
  if (table === undefined) {
    table = safeTable(safe);
    tableCache.set(safe, table);
  }
  return table;
}

/** Python's `urllib.parse.quote(string, safe)`. */
export function quote(string, safe = '/') {
  const table = tableFor(safe);
  const bytes = encoder.encode(string);
  let out = '';
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    if (table[b]) out += String.fromCharCode(b);
    else out += '%' + HEX[b >> 4] + HEX[b & 0xf];
  }
  return out;
}

/** Python's `urllib.parse.quote_plus(string, safe)`. */
export function quotePlus(string, safe = '') {
  if (!string.includes(' ')) return quote(string, safe);
  return quote(string, safe + ' ').split(' ').join('+');
}

function hexValue(code) {
  if (code >= 0x30 && code <= 0x39) return code - 0x30;
  if (code >= 0x41 && code <= 0x46) return code - 0x37;
  if (code >= 0x61 && code <= 0x66) return code - 0x57;
  return -1;
}

/** Python's `urllib.parse.unquote_to_bytes(string)`. */
export function unquoteToBytes(string) {
  const bytes = encoder.encode(string);
  const out = [];
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === 0x25 /* '%' */ && i + 2 < bytes.length) {
      const hi = hexValue(bytes[i + 1]);
      const lo = hexValue(bytes[i + 2]);
      if (hi >= 0 && lo >= 0) {
        out.push((hi << 4) | lo);
        i += 2;
        continue;
      }
    }
    out.push(bytes[i]);
  }
  return Uint8Array.from(out);
}

/** Python's `urllib.parse.unquote(string)` with `errors='replace'`. */
export function unquote(string) {
  if (!string.includes('%')) return string;
  return decoder.decode(unquoteToBytes(string));
}

/** Python's `urllib.parse.unquote_plus(string)`. */
export function unquotePlus(string) {
  return unquote(string.split('+').join(' '));
}

