/**
 * Minimal IDNA (RFC 3490) ToASCII, enough to mirror Python's
 * `host.encode('idna')` for the hostnames furl accepts.
 *
 * Pure-ASCII labels are passed through untouched (as CPython's ToASCII does);
 * anything else is NFKC-normalised and punycode-encoded.
 */

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';

function adapt(delta, numPoints, firstTime) {
  let d = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  d += Math.floor(d / numPoints);
  let k = 0;
  while (d > ((BASE - TMIN) * TMAX) >> 1) {
    d = Math.floor(d / (BASE - TMIN));
    k += BASE;
  }
  return k + Math.floor(((BASE - TMIN + 1) * d) / (d + SKEW));
}

function digitToBasic(digit) {
  // 0..25 -> 'a'..'z', 26..35 -> '0'..'9'
  return String.fromCharCode(digit + 22 + (digit < 26 ? 75 : 0));
}

/** RFC 3492 punycode encoding of a single label. */
export function punycodeEncode(input) {
  const codePoints = Array.from(input, (ch) => ch.codePointAt(0));
  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  const basic = codePoints.filter((cp) => cp < 0x80);
  let handled = basic.length;
  let out = basic.map((cp) => String.fromCharCode(cp)).join('');
  if (handled > 0) out += DELIMITER;

  while (handled < codePoints.length) {
    let m = Infinity;
    for (const cp of codePoints) if (cp >= n && cp < m) m = cp;
    delta += (m - n) * (handled + 1);
    n = m;
    for (const cp of codePoints) {
      if (cp < n) delta++;
      else if (cp === n) {
        let q = delta;
        for (let k = BASE; ; k += BASE) {
          const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
          if (q < t) break;
          out += digitToBasic(t + ((q - t) % (BASE - t)));
          q = Math.floor((q - t) / (BASE - t));
        }
        out += digitToBasic(q);
        bias = adapt(delta, handled + 1, handled === basic.length);
        delta = 0;
        handled++;
      }
    }
    delta++;
    n++;
  }
  return out;
}

function isAscii(text) {
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) > 0x7f) return false;
  return true;
}

function labelToAscii(label) {
  if (isAscii(label)) return label;
  const prepped = label.normalize('NFKC').toLowerCase();
  if (isAscii(prepped)) return prepped;
  return 'xn--' + punycodeEncode(prepped);
}

/** Python's `host.encode('idna').decode()` for dotted hostnames. */
export function idnaEncode(host) {
  if (isAscii(host)) return host;
  const labels = host.split('.');
  let trailingDot = '';
  if (labels.length > 1 && labels[labels.length - 1] === '') {
    labels.pop();
    trailingDot = '.';
  }
  return labels.map(labelToAscii).join('.') + trailingDot;
}

